const values = [41, 4, 13, 13, 4];
const kept = values.filter((value) => value < 24);
const largest = Math.max(...kept);
const edges = [
  { from: 4, to: 13 },
  { from: 13, to: 41 }
];

const hasPath = (from, to) => {
  const queue = [from];
  while (queue.length > 0) {
    const current = queue.shift();
    if (current === to) return true;
    for (const edge of edges) {
      if (edge.from === current && edge.to === to) return true;
      if (edge.from === current && edge.to !== to) queue.push(edge.to);
      if (edge.to === current && edge.from !== to) queue.push(edge.from);
    }
  }
  return false;
};

console.log(hasPath(4, 41)); // true
```

